import{_ as s,C as r,o as t,c as i,a2 as o,b as d,w as n,a as c,E as h,a3 as l}from"./chunks/framework.gExYLvYZ.js";const y=JSON.parse('{"title":"Integration Model","description":"How hookshot models integrations — the Connection abstraction that makes every service work the same way","frontmatter":{"title":"Integration Model","description":"How hookshot models integrations — the Connection abstraction that makes every service work the same way","audience":["evaluator","developer","operator","contributor"]},"headers":[],"relativePath":"understand/integration-model.md","filePath":"understand/integration-model.md","lastUpdated":1775242895000}'),p={name:"understand/integration-model.md"};function g(m,e,u,b,v,f){const a=r("Mermaid");return t(),i("div",null,[e[1]||(e[1]=o(`<h1 id="integration-model" tabindex="-1">Integration Model <a class="header-anchor" href="#integration-model" aria-label="Permalink to &quot;Integration Model&quot;">​</a></h1><p>Every hookshot integration — GitHub, GitLab, JIRA, webhooks, feeds — follows the same pattern. Understanding this pattern once means you can predict how any integration works.</p><h2 id="the-connection" tabindex="-1">The Connection <a class="header-anchor" href="#the-connection" aria-label="Permalink to &quot;The Connection&quot;">​</a></h2><p>A <strong>connection</strong> is a binding between a Matrix room and an external resource. It defines:</p><ul><li><strong>What to watch</strong> — which external events to deliver as Matrix messages</li><li><strong>What to accept</strong> — which bot commands to handle</li><li><strong>How to authenticate</strong> — credentials for the external service</li><li><strong>Where to store config</strong> — as a Matrix room state event</li></ul><p>One room can have multiple connections. One external resource can be connected to multiple rooms.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light tokyo-night vp-code" tabindex="0"><code><span class="line"><span>Matrix Room                         External Services</span></span>
<span class="line"><span>┌──────────────────────┐</span></span>
<span class="line"><span>│ #backend:example.com │───── GitHub: org/backend (PRs, issues)</span></span>
<span class="line"><span>│                      │───── Generic webhook: CI alerts</span></span>
<span class="line"><span>│                      │───── RSS: team blog</span></span>
<span class="line"><span>└──────────────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>┌──────────────────────┐</span></span>
<span class="line"><span>│ #frontend:example.com│───── GitHub: org/frontend (PRs only)</span></span>
<span class="line"><span>│                      │───── GitLab: org/design-system</span></span>
<span class="line"><span>└──────────────────────┘</span></span></code></pre></div><h2 id="every-connection-has-the-same-lifecycle" tabindex="-1">Every connection has the same lifecycle <a class="header-anchor" href="#every-connection-has-the-same-lifecycle" aria-label="Permalink to &quot;Every connection has the same lifecycle&quot;">​</a></h2>`,8)),(t(),d(l,null,{default:n(()=>[h(a,{id:"mermaid-41",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BCreated%5D%20--%3E%20B%5BStored%20as%20room%20state%5D%0A%20%20%20%20B%20--%3E%20C%5BActive%3A%20processing%20events%5D%0A%20%20%20%20C%20--%3E%20D%5BUpdated%20via%20state%20event%5D%0A%20%20%20%20D%20--%3E%20C%0A%20%20%20%20C%20--%3E%20E%5BRemoved%5D%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<ol><li><strong>Created</strong> — via bot command, widget, provisioning API, or direct state event</li><li><strong>Stored</strong> — configuration written as a Matrix room state event (e.g., <code>uk.half-shot.matrix-hookshot.github.repository</code>)</li><li><strong>Active</strong> — hookshot routes matching events to the connection&#39;s handlers</li><li><strong>Updated</strong> — new state event overwrites the old one; connection reconfigures</li><li><strong>Removed</strong> — state event cleared; connection deregistered</li></ol><p>The state event <strong>is</strong> the connection. When hookshot restarts, it reads all room state events and reconstructs every connection. No external database.</p><h2 id="every-connection-has-the-same-capabilities-in-theory" tabindex="-1">Every connection has the same capabilities (in theory) <a class="header-anchor" href="#every-connection-has-the-same-capabilities-in-theory" aria-label="Permalink to &quot;Every connection has the same capabilities (in theory)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td><strong>Inbound events</strong></td><td>External service → Matrix message</td><td>GitHub PR opened → room notification</td></tr><tr><td><strong>Outbound commands</strong></td><td>Bot command → external API call</td><td><code>!gh create &quot;Bug&quot;</code> → GitHub issue</td></tr><tr><td><strong>Provisioning</strong></td><td>Create/update/delete via API or UI</td><td>Widget form → new connection</td></tr><tr><td><strong>State storage</strong></td><td>Config stored as room state event</td><td><code>enableHooks: [&quot;issue.created&quot;]</code></td></tr></tbody></table><p>Not every connection implements all capabilities. Feeds have no outbound commands. Generic webhooks have no OAuth. But the model is the same.</p><h2 id="four-ways-to-create-a-connection" tabindex="-1">Four ways to create a connection <a class="header-anchor" href="#four-ways-to-create-a-connection" aria-label="Permalink to &quot;Four ways to create a connection&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Who uses it</th><th>How</th></tr></thead><tbody><tr><td><strong>Bot command</strong></td><td>Room users</td><td><code>!hookshot github repo https://github.com/org/repo</code></td></tr><tr><td><strong>Widget UI</strong></td><td>Room users</td><td>Click through the embedded web form</td></tr><tr><td><strong>Provisioning API</strong></td><td>Developers</td><td><code>POST /widgetapi/v1/{roomId}/connections/GitHubRepo</code></td></tr><tr><td><strong>Static config</strong></td><td>Operators</td><td>Pre-define connections in <code>config.yml</code></td></tr></tbody></table><p>All four paths end the same way: a state event is written to the room.</p><h2 id="how-events-route-to-connections" tabindex="-1">How events route to connections <a class="header-anchor" href="#how-events-route-to-connections" aria-label="Permalink to &quot;How events route to connections&quot;">​</a></h2><p>When an external event arrives (a webhook, a feed update), hookshot must find which connection(s) should handle it.</p><ol><li><strong>Service router</strong> identifies the service (GitHub, GitLab, etc.) from the URL path</li><li><strong>Event payload</strong> identifies the specific resource (which repo, which project)</li><li><strong>ConnectionManager</strong> looks up all connections matching that resource</li><li>Each matching connection&#39;s <strong>handler</strong> is called</li></ol><p>A GitHub webhook for <code>org/repo</code> will reach every <code>GitHubRepoConnection</code> connected to <code>org/repo</code>, regardless of which room it&#39;s in. If three rooms are connected to the same repo, all three get the notification.</p><h2 id="how-commands-route-to-connections" tabindex="-1">How commands route to connections <a class="header-anchor" href="#how-commands-route-to-connections" aria-label="Permalink to &quot;How commands route to connections&quot;">​</a></h2><p>When a user sends <code>!gh create &quot;Bug&quot;</code> in a room:</p><ol><li><strong>Bridge</strong> receives the room message via appservice API</li><li><strong>Command prefix</strong> (<code>!gh</code>) identifies which connection type to target</li><li><strong>Room connections</strong> are searched for a matching connection</li><li>The connection&#39;s <strong>command handler</strong> executes the action</li></ol><p>If a room has both a GitHub and GitLab connection, <code>!gh</code> goes to GitHub and <code>!gl</code> goes to GitLab. Each connection type defines its own prefix.</p><h2 id="the-pattern-is-the-same-for-every-service" tabindex="-1">The pattern is the same for every service <a class="header-anchor" href="#the-pattern-is-the-same-for-every-service" aria-label="Permalink to &quot;The pattern is the same for every service&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>GitHub</th><th>GitLab</th><th>JIRA</th><th>Generic Webhook</th><th>RSS Feed</th></tr></thead><tbody><tr><td><strong>Inbound source</strong></td><td>GitHub App webhook</td><td>GitLab webhook</td><td>JIRA webhook</td><td>Any HTTP POST</td><td>Polling</td></tr><tr><td><strong>State event</strong></td><td><code>...github.repository</code></td><td><code>...gitlab.repository</code></td><td><code>...jira.project</code></td><td><code>...generic.hook</code></td><td><code>...feed</code></td></tr><tr><td><strong>Command prefix</strong></td><td><code>!gh</code></td><td><code>!gl</code></td><td><code>!jira</code></td><td>—</td><td>—</td></tr><tr><td><strong>Auth</strong></td><td>GitHub App + OAuth</td><td>Token</td><td>OAuth 2.0/1.0</td><td>URL-based</td><td>None</td></tr><tr><td><strong>Provisioning</strong></td><td>All 4 methods</td><td>All 4 methods</td><td>All 4 methods</td><td>All 4 methods</td><td>All 4 methods</td></tr></tbody></table><p>The differences are in the details (which events, which commands, which auth flow). The architecture is identical.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./what-is-hookshot">What is Hookshot</a> — System overview</li><li><a href="./event-lifecycle">Event Lifecycle</a> — How events flow</li><li><a href="./../architecture/connections">Architecture: Connections</a> — Deep dive into the Connection abstraction</li><li><a href="./../integrations/overview">Integration Overview</a> — All services and capabilities</li></ul>',21))])}const k=s(p,[["render",g]]);export{y as __pageData,k as default};
